<?php
declare(strict_types=1);
$monthStartDate = DateTimeImmutable::createFromFormat('!Y-m-d', ($calendarMonth ?? date('Y-m')).'-01') ?: new DateTimeImmutable('first day of this month');
$daysInMonth = (int)$monthStartDate->format('t');
$firstWeekday = (int)$monthStartDate->format('N') - 1;
$today = date('Y-m-d');
$monthLabels = [1=>'January',2=>'February',3=>'March',4=>'April',5=>'May',6=>'June',7=>'July',8=>'August',9=>'September',10=>'October',11=>'November',12=>'December'];
$bookingForDay = static function(string $day) use ($calendarBookings): ?array {
    foreach (($calendarBookings ?? []) as $booking) {
        if ($day >= $booking['check_in'] && $day < $booking['check_out']) return $booking;
    }
    return null;
};
$ruleForDay = static function(string $day) use ($ranges): ?array {
    foreach (($ranges ?? []) as $range) {
        if ($day >= $range['date_from'] && $day < $range['date_to']) return $range;
    }
    return null;
};
