<div class="legend"><span><i class="dot available-dot"></i>Available</span><span><i class="dot blocked-dot"></i>Blocked</span><span><i class="dot pending-dot"></i>Pending confirmation</span><span><i class="dot confirmed-dot"></i>Confirmed</span></div>
<div class="calendar">
<?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $weekday): ?><div class="weekday"><?= $weekday ?></div><?php endforeach; ?>
<?php for($i=0;$i<$firstWeekday;$i++): ?><div class="day empty"></div><?php endfor; ?>
<?php for($dayNo=1;$dayNo<=$daysInMonth;$dayNo++):
 $dayDate=$monthStartDate->setDate((int)$monthStartDate->format('Y'),(int)$monthStartDate->format('n'),$dayNo);$day=$dayDate->format('Y-m-d');$booking=$bookingForDay($day);$rule=$ruleForDay($day);$classes=['day'];if($day===$today)$classes[]='today';if($day<$today)$classes[]='past';
 $label='Available';$class='available';$price=null;
 if($booking){$class=$booking['status']==='confirmed'?'booked':'pending';$label=$booking['status']==='confirmed'?'Rezervasyon onaylı':'Rezervasyon talebi';}
 elseif($rule && $rule['status']!=='available'){$class='blocked';$label='Takvimde kapalı';}
 elseif($rule && $rule['nightly_price']!==null){$price=(float)$rule['nightly_price'];}
 $classes[]=$class;
?><div class="<?= e(implode(' ',$classes)) ?>"><span class="num"><?= $dayNo ?></span><span class="state"><?= e($label) ?></span><?php if($booking): ?><span class="price"><?= e($booking['booking_code'] ?: 'Rezervasyon') ?></span><?php elseif($price!==null): ?><span class="price"><?= e(number_format($price,0,',','.')) ?> <?= e($property['currency']??'TRY') ?></span><?php endif; ?></div><?php endfor; ?>
</div>
<p class="muted" style="font-size:12px;margin-bottom:0">Her hücre bir geceyi temsil eder. Çıkış tarihi konaklama gecesi sayılmaz; bu tarihte yeni bir misafir giriş yapabilir.</p>
</section>
