<section class="panel"><h2>Takvim kurallarını düzenle</h2><p class="muted" style="font-size:12px">Tarihleri, müsaitlik durumunu ve gecelik özel fiyatı doğrudan değiştirebilirsin.</p><div class="table-wrap"><table><thead><tr><th>Başlangıç</th><th>Bitiş</th><th>Durum</th><th>Gecelik fiyat</th><th>Save / sil</th></tr></thead><tbody><?php foreach($ranges as $range): $formId='rule-'.$range['id']; ?><tr><td><form id="<?= e($formId) ?>" method="post" action="<?= e(app_url($saveUrl)) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$range['id'] ?>"><input type="hidden" name="property_id" value="<?= (int)$property['id'] ?>"></form><input type="date" name="date_from" value="<?= e($range['date_from']) ?>" form="<?= e($formId) ?>" required></td><td><input type="date" name="date_to" value="<?= e($range['date_to']) ?>" form="<?= e($formId) ?>" required></td><td><select name="status" form="<?= e($formId) ?>"><option value="blocked" <?= $range['status']==='blocked'?'selected':'' ?>>Blocked</option><option value="available" <?= $range['status']==='available'?'selected':'' ?>>Available</option></select></td><td><input type="number" name="nightly_price" min="0" step=".01" placeholder="Temel fiyat" value="<?= $range['nightly_price']!==null?e((string)$range['nightly_price']):'' ?>" form="<?= e($formId) ?>"></td><td><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn" type="submit" form="<?= e($formId) ?>">Save</button><form method="post" action="<?= e(app_url($deleteUrl)) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$range['id'] ?>"><input type="hidden" name="property_id" value="<?= (int)$property['id'] ?>"><button class="btn danger">Sil</button></form></div></td></tr><?php endforeach; ?><?php if(!$ranges): ?><tr><td colspan="5" class="empty-state">Bu ay için kayıtlı takvim kuralı yok.</td></tr><?php endif; ?></tbody></table></div></section>
